import base64, io, json, re
from pathlib import Path
from PIL import Image

IMAGE = ''
root = Path('_site')
root.mkdir(exist_ok=True)
image = Image.open(io.BytesIO(base64.b64decode(IMAGE))).convert('RGB')
for size in (180, 192, 512):
    image.resize((size, size), Image.Resampling.LANCZOS).save(root / f'cutpilot-{size}.png')
meta = '<meta name="application-name" content="CNC CutPilot"><meta name="apple-mobile-web-app-title" content="CNC CutPilot"><meta name="apple-mobile-web-app-capable" content="yes"><meta name="theme-color" content="#123f76"><link rel="apple-touch-icon" sizes="180x180" href="./cutpilot-180.png"><link rel="icon" type="image/png" href="./cutpilot-192.png"><link rel="manifest" href="./manifest.webmanifest">'
for name in ('index.html', 'assistant.html'):
    text = Path(name).read_text(encoding='utf-8')
    text = re.sub(r'<title>.*?</title>', '<title>CNC CutPilot | Parametri di taglio</title>' + meta, text, count=1, flags=re.S)
    logo = '<img src="./cutpilot-180.png" alt="Logo CNC CutPilot" width="76" height="76" style="border-radius:16px;vertical-align:middle;margin-right:14px"><span style="font-size:26px;font-weight:800">CNC CutPilot</span><p>Parametri di taglio, sotto controllo.</p>'
    text = re.sub(r'(<header[^>]*>)', lambda m: m.group(1) + logo, text, count=1)
    (root / name).write_text(text, encoding='utf-8')
manifest = {'id':'./', 'name':'CNC CutPilot', 'short_name':'CutPilot', 'description':'Parametri di taglio, sotto controllo.', 'start_url':'./assistant.html', 'scope':'./', 'display':'standalone', 'background_color':'#eff3f8', 'theme_color':'#123f76', 'icons':[{'src':f'./cutpilot-{s}.png', 'sizes':f'{s}x{s}', 'type':'image/png', 'purpose':'any'} for s in (192,512)]}
(root / 'manifest.webmanifest').write_text(json.dumps(manifest, ensure_ascii=False), encoding='utf-8')
(root / '.nojekyll').touch()
print('CNC CutPilot: pagine e icone generate senza modificare i calcoli.')
